/**
 * ⚑ S291 — the site viewer's content: data/strings/era_sites_model.json, GENERATED by tools/gen_era_sites.mjs from the
 * same data as the HTML pages under public/sites/ (so the page and the window in the piece cannot disagree).
 * Plain strings only; this file only gives them types.
 */
import raw from '../../../data/strings/era_sites_model.json';
import type { Status, Year } from './skins';

export interface Link { label: string; url: string; note?: string }
export type Block =
  | { k: 'h2' | 'h3' | 'h4'; t: string; status?: Status; tag?: string }
  | { k: 'p' | 'lede' | 'small' | 'note'; t: string }
  | { k: 'quote'; t: string; status: Status; tag: string; long: string }
  | { k: 'dl'; rows: [string, string][] }
  | { k: 'ul'; items: { t: string; sub?: string }[] }
  | { k: 'mono'; lines: string[] }
  | { k: 'src'; status: Status; tag: string; conf: string; t: string; links: { label: string; url: string }[]; nolink: string }
  | { k: 'links'; items: Link[] }
  | { k: 'key'; t: string; rows: { status: Status; tag: string; long: string }[] }
  | { k: 'fig'; img: string; w: number; h: number; alt: string; caption: string; credit: string }
  | { k: 'media'; title: string; what: string; file: string; type: string; credit: string; lyrics: string[]; lyricsTitle: string }
  | { k: 'terms'; rows: { term: string; status: string; def: string }[] }
  | { k: 'beats'; items: { label: string; opt: string; hint: string; where: string }[] }
  | { k: 'pagelink'; label: string; note: string; href: string }
  /** the hub's four doors (built in the viewer from HubModel, not in the generated file) */
  | { k: 'doors'; items: { year: Year; who: string; text: string }[] };

export type MediaBlock = Extract<Block, { k: 'media' }>;

export type TabId = 'story' | 'practices' | 'sources' | 'images' | 'media' | 'words' | 'missed';

export interface EraModel { heading: string; tagline: string; who: string; glance: [string, string][]; tabs: Record<TabId, Block[]> }
export interface HubModel {
  title: string; lede: string; choose: string; doors: { year: Year; who: string; text: string }[];
  alsoTitle: string; oldSources: string; oldSourcesNote: string;
  /** ⚑ S371 — the sound and film of the whole piece: the opening film, then the music that belongs to no one year */
  soundTitle: string; soundLead: string; film: MediaBlock; sound: MediaBlock[];
  lexiconTitle: string; lexiconLead: string; lexiconLinks: { label: string; url: string }[];
  aboutTitle: string; about: string[]; howTitle: string; how: string[];
}
export interface SiteModel {
  siteName: string; projectLine: string; updated: string; tabIds: TabId[]; tabs: Record<TabId, string>; tabsLabel: string;
  contentNote: string; records: string; hub: HubModel; eras: Record<Year, EraModel>;
}

export const MODEL = raw as unknown as SiteModel;
export const YEARS: Year[] = ['1997', '2003', '2016', '2026'];
